class Tokenizer:
    """Tokenizes arithmetic expressions into numbers, operators, and parentheses."""

    TOKEN_PATTERN = re.compile(r'\s*(\d+\.?\d*|\.\d+|[+\-*/()])\s*')
    VALID_CHARS = re.compile(r'^[\d\s+\-*/().]+$')

    def __init__(self, expression):
        self.expression = expression
        self.pos = 0
        self.tokens = []

    def tokenize(self):
        expr = self.expression.strip()
        if not expr:
            raise ExpressionError("Empty expression")

        # Check for invalid characters
        if not self.VALID_CHARS.match(expr):
            raise ExpressionError("Invalid characters in expression")

        pos = 0
        while pos < len(expr):
            # Skip whitespace
            while pos < len(expr) and expr[pos].isspace():
                pos += 1
            if pos >= len(expr):
                break

            # Try to match a token
            match = self.TOKEN_PATTERN.match(expr, pos)
            if not match:
                raise ExpressionError(f"Invalid token at position {pos}")

            token = match.group(1)
            self.tokens.append(token)
            pos = match.end()

        if not self.tokens:
            raise ExpressionError("Empty expression")

        return self.tokens


class Parser:
    """
    Recursive descent parser for arithmetic expressions.
    Grammar:
        expr   -> term (('+' | '-') term)*
        term   -> factor (('*' | '/') factor)*
        factor -> '-' factor | primary
        primary -> NUMBER | '(' expr ')'
    """

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        token = self.peek()
        self.pos += 1
        return token

    def parse(self):
        result = self.expr()
        if self.pos < len(self.tokens):
            raise ExpressionError(f"Unexpected token: {self.peek()}")
        return result

    def expr(self):
        """Parse addition and subtraction (lowest precedence)."""
        left = self.term()

        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def term(self):
        """Parse multiplication and division (higher precedence)."""
        left = self.factor()

        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.factor()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ExpressionError("Division by zero")
                left = left / right

        return left

    def factor(self):
        """Parse unary minus and primary expressions."""
        if self.peek() == '-':
            self.consume()
            return -self.factor()
        return self.primary()

    def primary(self):
        """Parse numbers and parenthesized expressions."""
        token = self.peek()

        if token is None:
            raise ExpressionError("Unexpected end of expression")

        if token == '(':
            self.consume()
            result = self.expr()
            if self.peek() != ')':
                raise ExpressionError("Unbalanced parentheses: missing ')'")
            self.consume()
            return result

        if token == ')':
            raise ExpressionError("Unbalanced parentheses: unexpected ')'")

        if token in ('+', '-', '*', '/'):
            raise ExpressionError(f"Unexpected operator: {token}")

        # Must be a number
        try:
            self.consume()
            return Decimal(token)
        except InvalidOperation:
            raise ExpressionError(f"Invalid number: {token}")


def evaluate_expression(expression):
    """
    Evaluate an arithmetic expression and return the result.
    Returns a properly formatted number (integer if whole, else up to 6 decimal places).
    """
    tokenizer = Tokenizer(expression)
    tokens = tokenizer.tokenize()

    parser = Parser(tokens)
    result = parser.parse()

    # Round to 6 decimal places using ROUND_HALF_UP
    result = result.quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP)

    # Normalize to remove trailing zeros
    result = result.normalize()

    # Convert to appropriate Python type
    if result == result.to_integral_value():
        return int(result)
    else:
        return float(result)


def add_to_history(expression, result):
